tafsir_text:
قوله :  {  احْشُرُوا الَّذِينَ ظَلَمُوا وَأَزْوَاجَهُمْ } أي :  سوقوا الذين أشركوا وأزواجهم ،   أي :  وأشكالهم .   [ وقال بعضهم :  {  وَأَزْوَاجَهُمْ } أي :  وقرناءهم من الشياطين ] {  وَمَا كَانُوا يَعْبُدُونَ مِن دُونِ اللهِ فَاهْدُوهُمْ إِلَى صِرَاطِ الجَحِيمِ } .

ذكروا عن النعمان بن بشير عن عمر بن الخطاب في قوله :  {  وَإِذَا النُّفُوسُ زُوِّجَتْ }

[ التكوير :  7 ] قال :  يزوّج كل إنسان نظيره من النار ،   ثم تلا هذه الآية :  {  احْشُرُوا الَّذِينَ ظَلَمُوا وَأَزْوَاجَهُمْ وَمَا كَانُوا يَعْبُدُونَ مِن دُونِ اللهِ فَاهْدُوهُمْ }

وقال الكلبي :  {  احْشُرُوا الَّذِينَ ظَلَمُوا } أي :  أشركوا ،   {  وَأَزْوَاجَهُمْ } أي :  ومن عمل بأعمالهم من بني آدم .

{  فَاهْدُوهُمْ }أي :  فادعوهم {  إِلَى صِرَاطِ الجَحِيمِ } .   تفسير الحسن :  أن كل قوم يلحقون بصنفهم .   {  وَمَا كَانُوا يَعْبُدُونَ مِن دُونِ اللهِ } في تفسير الحسن ،   بمعنى الشياطين التي دعتهم إلى عبادة الأوثان ،   وإنما عبدوا الشياطين .

قوله :  {  فَاهْدُوهُمْ إِلَى صِرَاطِ الجَحِيمِ } أي :  إلى طريق الجحيم .   والجحيم اسم من أسماء جهنم ،   وهو الباب الخامس ،   وإنما أبوابها سبعة :  جهنم ،   وهو الباب الأعلى ،   ثم لظى ،   ثم الحطمة ،   ثم السعير ،   ثم الجحيم ،   ثم سقر ،   ثم الهاوية ،   وهي الدرك الأسفل من النار ،   وجهنم اسم جامع لتلك الأبواب .   قال :  {  فَادْخُلُوا أَبْوَابَ جَهَنَّمَ } [ النحل :  29 ] وكل باب منها هو النار ،   الأعلى جهنم ،   ثم لظى ،   والنار كلها لظى .   قال :  {  فَأَنذَرْتُكُمْ نَاراً تَلَظَّى } [ الليل :  14 ] أي :  تأجج .   ثم الحطمة ،   والنار كلها حطمة ،   أي :  تحطم عظامهم وتأكل كل شيء منهم إلا الفؤاد .   قال :  {  كَلاَّ لَيُنبَذَنَّ فِي الحُطَمَةِ } [ الهمزة :  4 ] ثم السعير ،   والنار كلها سعير ،   تسعر عليهم ،   قال :  {  وَسَيَصْلَوْنَ سَعِيراً } [ النساء :  10 ] ثم الجحيم ،   والنار كلها جحيم ،   قال :  {  قَالُوا ابْنُوا لَهُ بُنْيَاناً فَأَلْقُوهُ فِي الجَحِيمِ } [ الصافات :  97 ] أي :  في النار .   ثم سقر ،   والنار كلها سقر .   قال :  {  سَأُصْلِيهِ سَقَرَ وَمَا أَدْرَاكَ مَا سَقَرُ لاَ تُبْقِي وَلاَ تَذَرُ } [ المدثر :  26-28 ] فكذلك تفعل تلك الأبواب كلها بهم ،   لا تبقي أجسادهم حين يدخلونها ولا تذر ،   أي :  حين يجدّد خلقهم حتى تأكل أجسادهم ،   وهو قوله :  {  كُلَّمَا نَضِجَتْ جُلُودُهُم بَدَّلْنَاهُمْ جُلُوداً غَيْرَهَا لِيَذُوقُوا الْعَذَابَ }

[ النساء :  56 ] ،   ثم الهاوية ،   والنار كلها هاوية ،   يهوون فيها .   قال :  {  فَأُمُّهُ هَاوِيَةٌ }

[ القارعة :  9 ] ،   غير أن هذه الأنواع التي وصف بها النار لكل باب من أبوابها اسم من تلك الأنواع سمّيت به ،   ولكل قوم من أهل النار منزل من تلك الأبواب التي سمّيت بهذه الأسماء .

{  سُبْحَانَ رَبِّكَ } ينزّه نفسه {  رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ } أي :  عما يكذبون ،  {  وسلام على المرسلين }يعني :  الثناء الحسن  ،   {  والحمد لله رب العالمين }

ذكروا عن أبي هارون العبدي قال :  سألت أبا سعيد الخدري :  بِمَ كان رسول الله صلى الله عليه وسلم يختم صلاته ،   فقال بهذه الآية :  {  سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ وَسَلاَمٌ عَلَى المُرْسَلِينَ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ } .

ذكروا عن علي بن أبي طالب قال :  من سرّه أن يكتال بالمكيال الأَوْفَى فليقل في دبر صلاته :  {  سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ وَسَلاَمٌ عَلَى المُرْسَلِينَ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ } .
